import { salaryZonedWallClockToUtcMs } from '../salaryZonedWallClock.ts'
import { APP_CALENDAR_TZ } from '../../utils/dateUtils.ts'

/**
 * When a desk item marked sent after the fact says it went (punch list #243, PR 2).
 *
 * A § 53.056 notice recorded by hand, the Lien window's *Save & record sends…* and a run recorded
 * in a later sitting all carry the mailing day the office typed inside the filing's `sends[].sent_on`.
 * The desk item they mark sent carried no `sent_at`, so the guard trigger on `job_lien_desk_items`
 * stamped `now()`, and letter two's clock, the courtesy notice's day 7 and the desk's day count all
 * started on the day of the typing, not the mailing (three live items read 14 days short on
 * 2026-11-02). These helpers give the write the typed day. Pure; the IO passes the answer on.
 */

const YMD = /^\d{4}-\d{2}-\d{2}$/

/**
 * Noon on the day in the app's calendar, as the instant a row keeps, so `calendarYmdInAppTzFromIso`
 * reads the day back in any zone (the pen record keeps its signing day the same way); null for
 * anything that is not a day.
 */
export function appTzNoonIso(ymd: string): string | null {
  const day = ymd.trim()
  if (!YMD.test(day)) return null
  const ms = salaryZonedWallClockToUtcMs(day, 12, 0, 0, APP_CALENDAR_TZ)
  return ms == null ? null : new Date(ms).toISOString()
}

/**
 * The `sent_at` a mark-sent write carries: noon of the typed day when that day is before today, so
 * every clock runs from the mailing day. Null when the day is today, ahead of today or not a day:
 * the trigger then stamps the moment of the write, as it always did, and a notice recorded the day
 * it goes out keeps its exact instant.
 */
export function sentAtForTypedDay(ymd: string | null | undefined, todayYmd: string): string | null {
  const day = (ymd ?? '').trim()
  if (!YMD.test(day) || day >= todayYmd) return null
  return appTzNoonIso(day)
}

/** The earliest `sent_on` among a filing's sends — the day the packet left; null when none says. */
export function earliestSendDay(sends: unknown): string | null {
  if (!Array.isArray(sends)) return null
  const days = sends
    .map((s) => (s && typeof s === 'object' ? (s as { sent_on?: unknown }).sent_on : null))
    .filter((d): d is string => typeof d === 'string' && YMD.test(d))
    .sort()
  return days[0] ?? null
}
